def _iter_block_paragraphs(parent_elm, doc):
    """Yield paragraphs under a body or table-cell element, descending INTO
    tables (including NESTED tables) so no cell text is silently dropped."""
    from docx.text.paragraph import Paragraph as _P
    from docx.table import Table as _T
    seen = set()
    for child in parent_elm.iterchildren():
        tag = child.tag.split("}")[-1] if "}" in child.tag else child.tag
        if tag == "p":
            yield _P(child, doc)
        elif tag == "tbl":
            table = _T(child, doc)
            for row in table.rows:
                for cell in row.cells:
                    tc = cell._tc
                    if tc in seen:
                        continue
                    seen.add(tc)
                    yield from _iter_block_paragraphs(tc, doc)


def iter_doc_paragraphs(doc):
    """Yield paragraphs in document order, descending into tables and nested
    tables so table-cell content is never lost."""
    yield from _iter_block_paragraphs(doc.element.body, doc)


def _paragraph_is_in_table(para):
    """True when a paragraph is inside a table cell. Table-cell text is content,
    not a structural heading signal, unless the user moves it into the body."""
    node = para._element.getparent()
    while node is not None:
        if node.tag == qn("w:tc"):
            return True
        node = node.getparent()
    return False


CAPTION_PATTERN = re.compile(
    r"^(figure|fig\.?|photo|photograph|image|plate|illustration|table|map)\s*"
    r"[\d ivxlcdm]+\s*[.:\-\u2014)]", re.IGNORECASE)


CHAPTER_PATTERN = re.compile(
    r"^(chapter\s+\d+|chapter\s+[ivxlcdm]+|chapter\s+\w+)([\s:.\-\u2014]|$)",
    re.IGNORECASE,
)


SECTION_HEADING_PATTERN = re.compile(
    r"^(prologue|epilogue|interlude|part\s+\w+)([\s:.\-\u2014]|$)",
    re.IGNORECASE,
)


SCENE_BREAK_PATTERN = re.compile(r"^(?:[*#~\u2022\-\u2014_=+]\s*){3,}$|^\u2042$")


LONE_SCENE_BREAK_PATTERN = re.compile(r"^[*#~\u2022\u2042\u2014]$")


def _indents_in(p):
    """(first-line indent, left indent, right indent) in inches, from the
    paragraph or its style chain. A hanging indent counts as none."""
    first = left = right = None
    fmt = p.paragraph_format
    first, left, right = fmt.first_line_indent, fmt.left_indent, fmt.right_indent
    st = p.style
    while st is not None and (first is None or left is None or right is None):
        sf = getattr(st, "paragraph_format", None)
        if sf is not None:
            first = sf.first_line_indent if first is None else first
            left = sf.left_indent if left is None else left
            right = sf.right_indent if right is None else right
        st = st.base_style
    conv = lambda v: (v.inches if hasattr(v, "inches") else 0.0) if v is not None else 0.0
    return max(0.0, conv(first)), max(0.0, conv(left)), max(0.0, conv(right))


def is_chapter_heading(text):
    """Detect chapter headings including 'Chapter N', 'Part X', 'Prologue', etc."""
    stripped = text.strip()
    if not stripped:
        return False
    if re.search(r"\.{3,}", stripped):
        return False
    if CHAPTER_PATTERN.match(stripped):
        # A real chapter heading is short and title-like. Guard against body
        # sentences that merely BEGIN with "Chapter 12 ..." (e.g. "Chapter 12 of
        # the report explains the survey.") being turned into a chapter break.
        # Mirrors the numbered/all-caps heading guards. Short "Chapter N",
        # "Chapter N.", and "Chapter N: Title" forms still pass.
        words = stripped.split()
        if len(words) > 12 or (_looks_like_sentence(stripped) and len(words) > 4):
            return False
        return True
    if SECTION_HEADING_PATTERN.match(stripped):
        # Same guard as the Chapter branch: a real "Part X" heading is short and
        # title-like, NOT a body sentence that merely begins with "Part ...".
        words = stripped.split()
        if len(words) > 12 or (_looks_like_sentence(stripped) and len(words) > 4):
            return False
        return True
    return False


_FRONT_TITLED = re.compile(r"^(preface|introduction|foreword)\s*[:\-\u2013\u2014]\s*\S")


def is_front_matter_heading(text):
    """Detect front matter section headings."""
    stripped = text.strip().lower()
    if stripped in (
        "dedication", "acknowledgments", "acknowledgements", "acknowledgment",
        "table of contents", "contents", "preface", "introduction",
        "foreword",
    ):
        return True
    # "Introduction: The Language of Guilt" - a front-matter heading with its
    # own title after a colon (Mike's Conversations with Killers, 2026-10-19:
    # it was printed as a plain body line inside an untitled opening).
    if _FRONT_TITLED.match(stripped) and len(stripped.split()) <= 12 \
            and not stripped.endswith((".", "?", "!")):
        return True
    # "Welcome to X!" style intros are treated as introduction/preface
    if stripped.startswith("welcome to "):
        _w = stripped.split()
        return not (len(_w) > 12 or (_looks_like_sentence(stripped) and len(_w) > 4))
    return False


def is_back_matter_heading(text):
    """Detect back matter section headings (exact or prefix match)."""
    stripped = text.strip().lower().replace("’", "'")
    exact = (
        "addendum", "appendix", "appendices", "index", "credits",
        "glossary", "bibliography", "references", "sources", "notes",
        "about the author", "about the publisher", "also by", "afterword",
        "author's note", "endnotes", "further reading", "permissions",
        "colophon", "bonus material", "contact the author",
        "resources & activities", "resources and activities",
        "resources", "activities", "discussion questions",
        "reading group guide", "book club questions",
        "connect the dots", "supporting our communities",
    )
    if stripped in exact:
        return True
    if re.match(r"^appendix\s+[a-z0-9]+(?:\s*[:\-\u2014]\s*[^.!?]+)?$", stripped):
        return len(stripped.split()) <= 12
    prefixes = ("about the ", "about me", "also by", "more by", "more works by", "other books by",
                "other titles by", "resources ", "glossary", "upper peninsula glossary")
    if any(stripped.startswith(p) for p in prefixes):
        _w = stripped.split()
        return not (len(_w) > 12 or (_looks_like_sentence(stripped) and len(_w) > 4))
    return False


NUMBERED_HEADING_PATTERN = re.compile(r"^\s*\d{1,3}\s*[.)\:\-–—]\s+\S")


_HEADING_END_PUNCT = (".", "!", "?", ";", ",")


HEADING_MODES = ("auto", "chapter", "styles", "numbered", "bold", "allcaps")


def _kdp_style_cache(para, bucket):
    """Per-document memo of anything that depends only on a paragraph's STYLE.
    python-docx resolves the default style from scratch on every
    paragraph.style call, so a long document pays that cost thousands of
    times. Measured 2026-09-16 on Apache POI's bug65649.docx (14,073
    paragraphs): the safety check took over four minutes and looked frozen
    to the buyer. Keyed by the style id on the paragraph (None = default)."""
    try:
        pPr = para._p.find(qn("w:pPr"))
        style_id = None
        if pPr is not None:
            pStyle = pPr.find(qn("w:pStyle"))
            if pStyle is not None:
                style_id = pStyle.get(qn("w:val"))
        part = para.part
        caches = getattr(part, "_kdp_style_caches", None)
        if caches is None:
            caches = {}
            setattr(part, "_kdp_style_caches", caches)
        return caches.setdefault(bucket, {}), style_id
    except Exception:
        return None, None


def _style_name_of(para):
    """para.style.name, worked out once per style instead of once per paragraph."""
    cache, key = _kdp_style_cache(para, "name")
    if cache is not None and key in cache:
        return cache[key]
    try:
        name = (para.style.name or "").strip().lower()
    except Exception:
        name = ""
    if cache is not None:
        cache[key] = name
    return name


def _outline_level_from_style(para):
    """Walk the paragraph's style chain for an explicit outline level. This is
    language-independent, so it catches localized ('Überschrift 1') and renamed
    heading styles that a name match would miss. Memoized per style, for the
    reason given in _kdp_style_cache."""
    cache, key = _kdp_style_cache(para, "outline")
    if cache is not None and key in cache:
        return cache[key]
    answer = _outline_level_uncached(para)
    if cache is not None:
        cache[key] = answer
    return answer


def _outline_level_uncached(para):
    try:
        st = para.style
        for _ in range(10):  # guard against cyclic base_style chains
            if st is None:
                break
            sppr = st.element.find(qn("w:pPr"))
            if sppr is not None:
                olvl = sppr.find(qn("w:outlineLvl"))
                if olvl is not None:
                    v = olvl.get(qn("w:val"))
                    if v is not None and 0 <= int(v) <= 8:
                        return int(v) + 1
            st = st.base_style
    except Exception:
        pass
    return None


def para_heading_level(para):
    """Word heading level (1-9) if the paragraph is styled as a heading, else
    None. Detected by (a) a 'Heading N' style name, (b) a direct outline level
    on the paragraph, or (c) an outline level inherited from the style chain.
    'Title'/'Subtitle' are intentionally NOT section heads (they're the book
    title, which the formatter regenerates as front matter)."""
    name = _style_name_of(para)
    if name in ("title", "subtitle"):
        return None
    if name.startswith("heading"):
        tail = name[len("heading"):].strip()
        if tail == "":
            return 1
        if tail.isdigit() and 1 <= int(tail) <= 9:
            return int(tail)
    # Direct outline level on the paragraph.
    try:
        ppr = para._p.find(qn("w:pPr"))
        if ppr is not None:
            olvl = ppr.find(qn("w:outlineLvl"))
            if olvl is not None:
                v = olvl.get(qn("w:val"))
                if v is not None and 0 <= int(v) <= 8:
                    return int(v) + 1
    except Exception:
        pass
    return _outline_level_from_style(para)


def _min_heading_level(doc):
    """Scan all paragraphs; return the minimum Word outline level (1-9) found, or
    None if no Word heading styles are present in the document."""
    min_level = None
    for para in iter_doc_paragraphs(doc):
        lvl = para_heading_level(para)
        if lvl is not None:
            if min_level is None or lvl < min_level:
                min_level = lvl
    return min_level


def _is_mostly_cjk(text):
    """True when most of the letters on the line are Chinese, Japanese or
    Korean. Those scripts have no capital letters, so text == text.upper() is
    true for every line of ordinary prose in them. Without this, an eight
    chapter Japanese novel came out as fifty-six chapters with no body text at
    all, and the program said Done. (R1, second audit 2026-09-22.)"""
    ranges = (
        (0x3040, 0x30ff),   # hiragana and katakana
        (0x3400, 0x4dbf),   # CJK ideographs, extension A
        (0x4e00, 0x9fff),   # CJK ideographs
        (0xf900, 0xfaff),   # compatibility ideographs
        (0xac00, 0xd7af),   # hangul syllables
        (0x1100, 0x11ff),   # hangul jamo
    )
    letters = [c for c in text if c.isalpha()]
    if not letters:
        return False
    cjk = sum(1 for c in letters
              if any(lo <= ord(c) <= hi for lo, hi in ranges))
    return cjk >= len(letters) * 0.5


_SENTENCE_ENDERS = (".", "!", "?", "\u3002", "\uff01", "\uff1f", "\uff0e",
                    "\u2026", "\u203c", "\u2047", "\u2048", "\u2049")


def _looks_like_sentence(text):
    """Ends in sentence punctuation \u2014 i.e. a body line / list step, not a title.
    The full-width Chinese and Japanese enders count too (R1, 2026-09-22)."""
    stripped = text.rstrip().rstrip("\u300d\u300f\u201d\u2019\uff09)\"'")
    return stripped.endswith(_SENTENCE_ENDERS)


def _is_numbered_heading(text):
    """'1. Title', '1) Title', '2: Title', '3 - Title' — short and title-like.
    Excludes numbered LIST / recipe steps ('1. Preheat the oven.'), which read
    as sentences and end in sentence punctuation."""
    if not NUMBERED_HEADING_PATTERN.match(text):
        return False
    if len(text.split()) > 12:
        return False
    return not _looks_like_sentence(text)


def _is_allcaps_heading(text):
    """A short ALL-CAPS line (e.g. 'FINAL REVIEW'). Uses an upper==self check so
    accented capitals (CAFÉ) still count, and excludes shouted SENTENCES that end
    in sentence punctuation so they aren't turned into chapters."""
    letters = [c for c in text if c.isalpha()]
    # The cheap tests run first (2026-10-20: running the script test first on
    # every line made the safety check take 30.5 s on a 15,000-paragraph book).
    # The answer is the same, because each test can only say no.
    if len(letters) < 2 or text != text.upper():
        return False
    if len(text.split()) > 8:
        return False
    # A script with no capital letters is not shouting (R1, 2026-09-22).
    if _is_mostly_cjk(text):
        return False
    return not _looks_like_sentence(text)


_ROMAN_HEADING = re.compile(
    r"^(?P<num>[IVXLCDM]+)\s*[.:)\u2014\-]?\s*(?P<rest>.*)$")


def _is_roman_heading(text):
    """A chapter headed with a roman numeral on its own \u2014 I, V, XIV, or
    "IV. The Lake". Until 2026-09-22 the one and two letter numerals I and V
    were thrown away by a "needs at least two letters" rule, so an eight
    chapter book came out with six, and the chapter-count gate could not see
    it because it only compares the build against what the parser found.
    (R3, second audit.)"""
    stripped = text.strip()
    if not stripped or len(stripped.split()) > 8:
        return False
    m = _ROMAN_HEADING.match(stripped)
    if not m:
        return False
    num = m.group("num")
    # Reject a shouted word that happens to use only roman letters, such as
    # MIX or DID, by insisting the numeral reads as a real number.
    if not re.fullmatch(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})",
                        num) or not num:
        return False
    rest = m.group("rest").strip()
    if rest and (_looks_like_sentence(rest) or len(rest.split()) > 7):
        return False
    return True


def _runin_heading_split(runs):
    """A CHAPTER TITLE TYPED INTO THE FRONT OF ITS FIRST PARAGRAPH, e.g. a bold
    "Chapter One." followed, in the same paragraph, by plain prose. Returns
    (title_text, leading_bold_run_count) or (None, 0).

    Until 2026-09-22 a book written this way was told "No chapter headings were
    found" while the buyer was looking at bold chapter titles on the screen
    (R8, second audit)."""
    real = [r for r in runs if r.text.strip()]
    if len(real) < 2:
        return None, 0
    lead = []
    for r in real:
        if r.bold:
            lead.append(r)
        else:
            break
    if not lead or len(lead) == len(real):
        return None, 0
    rest = "".join(r.text for r in real[len(lead):]).strip()
    if len(rest.split()) < 5:
        return None, 0          # a bold opening phrase, not a title over prose
    if any(r.bold for r in real[len(lead):]):
        return None, 0          # bold scattered through the line, not a title
    title = "".join(r.text for r in lead).strip()
    if not title or len(title.split()) > 12:
        return None, 0
    title = title.rstrip(" \t\u2014-:.")
    if not title:
        return None, 0
    return title, len(lead)


def _is_bold_short_heading(text, runs):
    """A standalone, fully-bold, short line that doesn't read like a sentence."""
    real = [r for r in runs if r.text.strip()]
    if not real or not all(r.bold for r in real):
        return False
    # Raised from 8 to 25 words on 2026-09-22 (R9, then raised again the same
    # day when a real 23-word title was still refused). Long chapter titles are
    # normal in literary and children's fiction, and the old cap refused them
    # while telling the buyer to make the line bold and centred, which it
    # already was. A sentence is still not a title, and that is what keeps
    # ordinary bold prose out. The character cap stops a whole bold paragraph
    # of short words from being read as a heading.
    # Raised again 2026-09-22 after a battery of deliberately awkward
    # manuscripts: a real 30-word chapter title was still being refused, and
    # the buyer was told to make the line bold and centred when it already was.
    # What keeps ordinary bold prose out is the sentence test below, not an
    # arbitrary word count, so the count is only a backstop now.
    if len(text.split()) > 40 or len(text) > 300:
        return False
    return not text.rstrip().endswith(_HEADING_END_PUNCT)


_FRONT_MATTER_WORDS = re.compile(
    r"copyright|\u00a9|all rights reserved|isbn|published by|publisher|"
    r"first edition|printed in|^by |^for |dedicat|acknowledg|table of contents|^contents$",
    re.I)


def _leading_chapter_lines(doc, limit=3):
    """Which of the first `limit` non-empty lines are real CHAPTER titles and
    not the author's own title block? Returns their TEXT (so the caller can
    match by text, never by a fragile line index).

    A leading bold short line is a chapter only when BOTH hold:
      1. nothing in the next three non-empty lines reads like a title page
         (copyright, ISBN, "by Author", "for Mom", publisher lines), and
      2. at least one more bold short line appears later in the book - so the
         bold-line route is really how this manuscript marks chapters.
    A bold line followed by a copyright paragraph stays a book title, however
    long that paragraph is. A bold line followed by a one-line piece of
    dialogue is still a chapter. (Rewritten after the second review 2026-09-10;
    the first version judged by "40 words of prose next", which turned a
    title over a long copyright paragraph into Chapter 1.)"""
    lines = []   # (text, looks_like_a_fuzzy_chapter_title)
    _fuzzy_seen = 0
    for para in iter_doc_paragraphs(doc):
        t = para.text.strip()
        if not t:
            continue
        runs = [r for r in para.runs if r.text.strip()]
        fuzzy = ((_is_bold_short_heading(t, runs) if runs else False)
                 or _is_allcaps_heading(t) or _is_numbered_heading(t)
                 or _is_roman_heading(t))
        lines.append((t, fuzzy))
        _fuzzy_seen += 1 if fuzzy else 0
        # Only the first limit+3 lines and "two or more chapter-like lines in
        # the whole book" decide the answer, so stop reading once both are
        # known (2026-10-20, speed of the safety check on long books).
        if len(lines) >= limit + 3 and _fuzzy_seen >= 2:
            break
    # ALL-CAPS and "1. Title" lines are chapter signals too (2026-09-10, edge
    # battery: a book whose chapters were ALL CAPS with one paragraph each
    # lost its first two chapters to this skip and was refused).
    # "At least one more bold short line appears later" is counted from the
    # candidate line itself, not from the end of the three-line window.
    # (H36, Gemini ruled 2026-09-17.) Counting from the window made a book
    # whose very first line is Chapter 1's bold title lose EVERY heading when
    # the only other bold line also sat inside the window - measured on a
    # two-chapter book with one paragraph each: zero chapters found, and the
    # safety check then refused it as "fewer than two chapters".
    # Whether the bold-line route is really how this manuscript marks its
    # chapters is a property of the WHOLE document (two or more such lines),
    # not of what happens to sit after the three-line window.
    bold_total = sum(1 for _t, b in lines if b)
    keep = set()
    for i in range(min(limit, len(lines))):
        text, bold = lines[i]
        if not bold or bold_total < 2:
            continue
        # Each following line is tested on its own so "^by " and "^for "
        # anchor to the start of a LINE, not of a joined blob.
        if any(_FRONT_MATTER_WORDS.search(t) for t, _b in lines[i + 1:i + 4]):
            continue
        keep.add(text)
    return keep


def make_heading_detector(mode, min_level=None, doc=None):
    """Return a callable is_heading(text, runs, para, nonempty_idx) for the given
    detection mode. 'chapter' is the original literal-only behavior; the broad
    signals (Word heading styles, numbered 'N.' lines, standalone bold/ALL-CAPS
    lines) are what let NUMBERED or NAMED nonfiction sections be recognized.

    When min_level is not None (meaning the document has Word heading styles),
    only paragraphs at exactly that level trigger a new chapter; lower heading
    levels (H2, H3, etc.) are handled separately as subheads. Fuzzy signals
    (numbered, bold, ALL-CAPS) are also disabled when styles are present."""
    has_styles = min_level is not None
    # Leading bold lines that are followed by real prose are chapter titles,
    # not a title block, and must not be skipped (see _leading_chapter_lines).
    leading_chapters = _leading_chapter_lines(doc) if doc is not None else set()
    # Is this a book numbered with roman numerals? Two or more such lines say
    # yes; one stray "I" in dialogue does not (R3, 2026-09-22).
    roman_book = False
    if doc is not None:
        _roman_seen = 0
        for _p in iter_doc_paragraphs(doc):
            _t = _p.text.strip()
            if _t and _is_roman_heading(_t):
                _roman_seen += 1
                if _roman_seen >= 2:
                    roman_book = True
                    break

    def detect(text, runs, para, idx):
        # Literal 'Chapter N' / 'Part X' / 'Prologue' always counts, every mode.
        if is_chapter_heading(text):
            return True
        if mode == "chapter":
            return False
        # Never reclassify a front/back-matter section name as a chapter.
        if is_front_matter_heading(text) or is_back_matter_heading(text):
            return False
        use_styles = mode in ("auto", "styles")
        # Fuzzy signals are disabled when real Word heading styles exist.
        use_number = mode in ("auto", "numbered") and not has_styles
        use_bold = mode in ("auto", "bold") and not has_styles
        use_caps = mode in ("auto", "allcaps") and not has_styles
        if use_styles and para is not None:
            lvl = para_heading_level(para)
            if lvl is not None:
                # With styles present, only the top-level (minimum) heading becomes
                # a chapter break; lower levels are demoted to subheads elsewhere.
                return lvl == min_level if has_styles else True
        if use_number and _is_numbered_heading(text):
            return True
        # Fuzzy bold / ALL-CAPS signals: skip the leading title block (the book's
        # own title/subtitle/byline sit in the first few lines and are often bold).
        if idx is not None and idx < 3 and text.strip() not in leading_chapters:
            return False
        if use_bold and _is_bold_short_heading(text, runs):
            return True
        if use_caps and _is_allcaps_heading(text):
            return True
        # Roman-numeral chapter numbers, including the single letters I and V
        # (R3, 2026-09-22). Only when the book really uses them: the detector
        # is handed the whole document through `doc`, and a stray "I" in prose
        # is a sentence, which _is_roman_heading already refuses.
        if use_caps and roman_book and _is_roman_heading(text):
            return True
        return False
    return detect


def is_scene_break(text):
    """Detect scene break markers like * * *, and a lone # (R6, 2026-09-22)."""
    t = text.strip()
    return bool(SCENE_BREAK_PATTERN.match(t) or LONE_SCENE_BREAK_PATTERN.match(t))


def is_toc_entry(text):
    """Detect TOC-style entries with dot leaders or tab-based page numbers."""
    t = text.strip()
    return (bool(re.search(r"\.{3,}\s*\d+\s*$", t)) or
            bool(re.search(r"\t\d+\s*$", t)))


class RichRun:
    """A text run with inline formatting.

    Underline, strike-through, small capitals and raised or lowered text were
    all thrown away until 2026-09-19. Measured that day: a paragraph mixing
    bold, italic, underline, strike-through, small capitals and a raised
    number came back with only the bold and the italic. Novels use small
    capitals for an opening line and strike-through for crossed-out diary
    entries, and nothing warned the author. They are carried now.
    """
    __slots__ = ("text", "bold", "italic", "underline", "strike",
                 "small_caps", "superscript", "subscript", "font")

    def __init__(self, text, bold=False, italic=False, underline=False,
                 strike=False, small_caps=False, superscript=False,
                 subscript=False, font=None):
        self.text = text
        # A picture-letter font such as Wingdings, kept for a character the
        # author typed with Insert, then Symbol (blind audit B4, 2026-09-25).
        # None means the book's own body font.
        self.font = font
        self.bold = bold
        self.italic = italic
        self.underline = underline
        self.strike = strike
        self.small_caps = small_caps
        self.superscript = superscript
        self.subscript = subscript


class ContentParagraph:
    """A paragraph that preserves inline formatting and images."""
    __slots__ = ("runs", "images", "is_scene_break", "is_epigraph", "is_caption", "list_kind", "list_level", "is_subhead", "is_title_style", "table_pos", "block_style")

    def __init__(self, runs=None, images=None, is_scene_break=False,
                 is_epigraph=False, is_caption=False, list_kind=None, is_subhead=False,
                 is_title_style=False, list_level=0):
        self.runs = runs or []
        self.images = images or []
        self.is_scene_break = is_scene_break
        self.is_epigraph = is_epigraph
        self.is_caption = is_caption
        self.list_kind = list_kind  # None | "bullet" | "number" (preserve Word lists)
        # How deep the list item sits: 0 for a main point, 1 for a sub-point,
        # and so on. Before 2026-09-22 every level printed flat (a V1.1 item
        # Mike asked to have fixed before launch instead).
        self.list_level = list_level
        # (table key, row, column, rows, columns) for a paragraph that sat in
        # a plain table, so the table is rebuilt as a real table with its
        # lines (2026-09-22). None for everything else.
        self.table_pos = None
        self.is_subhead = is_subhead
        # True when the source paragraph used Word's "Title" or "Subtitle"
        # style. Those are the manuscript's own title page, which this
        # formatter regenerates as front matter.
        self.is_title_style = is_title_style
        # S8 (Gemini 2026-10-24): "indent" when the author styled the
        # paragraph Quote or indented its left edge in Word (a letter, a diary
        # entry, a quoted passage), "right" when the author right-aligned a
        # short line (a sign-off). The formatter keeps that setup instead of
        # guessing what is a letter. None for everything else.
        self.block_style = None

    @property
    def text(self):
        return "".join(r.text for r in self.runs)


NOTES_SECTION_TITLE = "Notes"


_NOTE_HOUSEKEEPING_TYPES = ("separator", "continuationSeparator", "continuationNotice")


_notes_state = {
    "root": None,     # the source document these numbers belong to
    "text": {},       # (kind, w:id) -> [RichRun, ...]
    "number": {},     # (kind, w:id) -> 1, 2, 3 ...
    "order": [],      # [(number, [RichRun, ...]), ...] in the order they are read
}


def _reset_notes_state():
    _notes_state["root"] = None
    _notes_state["text"] = {}
    _notes_state["number"] = {}
    _notes_state["order"] = []


def _note_part_blob(doc, partname):
    """Return the raw XML of word/footnotes.xml or word/endnotes.xml, or None."""
    try:
        for part in doc.part.package.iter_parts():
            if str(part.partname).lower() == partname:
                return part.blob
    except Exception:
        pass
    return None


def _note_runs_from_element(note_el):
    """Pull one note's words out as RichRuns, keeping bold and italic.

    A note written over several paragraphs is joined into one paragraph with a
    space between, because a note at the back of a book is printed as a single
    entry.
    """
    runs = []
    images = []
    for para in note_el.findall(qn("w:p")):
        mark = len(runs)
        for r in para.iter(qn("w:r")):
            _extract_run_into(r, runs, images, with_notes=False)
        if mark and len(runs) > mark:
            runs.insert(mark, RichRun(" "))
    # Word puts the note's own number and a tab at the front of the note text.
    while runs and not runs[0].text.strip():
        runs.pop(0)
    if runs:
        runs[0].text = runs[0].text.lstrip()
        runs[-1].text = runs[-1].text.rstrip()
    return [r for r in runs if r.text]


def load_notes(doc):
    """Read the manuscript's real footnotes and endnotes and number them 1, 2,
    3 ... in the order a reader meets them in the book."""
    _reset_notes_state()
    root = getattr(doc, "element", None)
    if root is None:
        return
    found = {}
    for kind, partname, tag in (
            ("footnote", "/word/footnotes.xml", qn("w:footnote")),
            ("endnote", "/word/endnotes.xml", qn("w:endnote"))):
        blob = _note_part_blob(doc, partname)
        if not blob:
            continue
        try:
            tree = parse_xml(blob)
        except Exception:
            continue
        for _gone in list(tree.iter(qn("w:del"))):
            if _gone.getparent() is not None:
                _gone.getparent().remove(_gone)
        flatten_source_wrappers(tree)
        for el in tree.findall(tag):
            if (el.get(qn("w:type")) or "").strip() in _NOTE_HOUSEKEEPING_TYPES:
                continue
            nid = el.get(qn("w:id"))
            if nid is None:
                continue
            note_runs = _note_runs_from_element(el)
            if not any(r.text.strip() for r in note_runs):
                continue
            found[(kind, str(nid))] = note_runs
    if not found:
        return
    _notes_state["root"] = root
    _notes_state["text"] = found
    ref_kind = {qn("w:footnoteReference"): "footnote",
                qn("w:endnoteReference"): "endnote"}
    for el in root.iter():
        kind = ref_kind.get(el.tag)
        if kind is None:
            continue
        key = (kind, str(el.get(qn("w:id"))))
        if key in found and key not in _notes_state["number"]:
            n = len(_notes_state["number"]) + 1
            _notes_state["number"][key] = n
            _notes_state["order"].append((n, found[key]))
    # A note whose raised number was deleted from the text still holds the
    # author's words. It is printed at the end of the list rather than lost.
    for key, note_runs in found.items():
        if key not in _notes_state["number"]:
            n = len(_notes_state["number"]) + 1
            _notes_state["number"][key] = n
            _notes_state["order"].append((n, note_runs))
    _kinds = set(k for k, _ in found)
    print("  Notes: %d footnote/endnote(s) found. They are printed as numbered "
          "endnotes under \"%s\" at the back of the book, with a raised number "
          "left where each one was." % (len(found), NOTES_SECTION_TITLE))


def _note_number_for(el, kind):
    """The printed number for one footnote/endnote reference, or None when the
    reference belongs to some other document (a stale reading) or to an entry
    that holds no words."""
    root = _notes_state["root"]
    if root is None or not _notes_state["number"]:
        return None
    try:
        if el.getroottree().getroot() is not root.getroottree().getroot():
            return None
    except Exception:
        return None
    return _notes_state["number"].get((kind, str(el.get(qn("w:id")))))


def _xml_toggle_on(rpr, tag):
    """True if a run-property toggle (w:b / w:i) is present AND not turned off.
    Word writes <w:b w:val="0"/> to CANCEL bold inherited from a style, so a bare
    presence check wrongly reads those runs as bold."""
    el = rpr.find(qn(tag))
    if el is None:
        return False
    val = el.get(qn("w:val"))
    return val is None or str(val).strip().lower() not in ("0", "false", "off", "none")


