_PICTURE_FONTS = ("wingdings", "webdings", "zapf dingbats", "marlett",
                  "mt extra", "ms outlook", "bookshelf symbol")


def _sym_is_picture_font(node):
    """True for a symbol typed in a picture-letter font (Wingdings and kin),
    whose characters have no plain-text meaning and must keep that font."""
    font = (node.get(qn("w:font")) or "").strip().lower()
    return any(font.startswith(p) for p in _PICTURE_FONTS)


def flatten_source_wrappers(root):
    """Open every wrapper Word puts around ordinary text, so the reader sees
    the words and pictures inside (blind audit B1-B4, 2026-09-25):
      content controls (w:sdt) round paragraphs, cells, rows or runs,
      tracked moves (the new place is kept, the old place dropped),
      hyperlinks (a printed book cannot click), text-direction wrappers,
      smart tags and custom-XML tags, simple fields,
      and AlternateContent (the preferred Choice is kept, the Fallback copy
      of the same thing dropped).
    Works on the document and on the footnote and endnote parts alike."""
    W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
    MCN = "http://schemas.openxmlformats.org/markup-compatibility/2006"
    if root is None:
        return root
    for tag in ("moveFrom", "moveFromRangeStart", "moveFromRangeEnd",
                "moveToRangeStart", "moveToRangeEnd"):
        for el in list(root.iter("{%s}%s" % (W, tag))):
            par = el.getparent()
            if par is not None:
                par.remove(el)

    def _unwrap(el, keep):
        par = el.getparent()
        if par is None:
            return
        idx = list(par).index(el)
        for child in list(keep):
            par.insert(idx, child)
            idx += 1
        par.remove(el)

    for ac in list(root.iter("{%s}AlternateContent" % MCN)):
        choice = ac.find("{%s}Choice" % MCN)
        pick = choice if choice is not None else ac.find("{%s}Fallback" % MCN)
        _unwrap(ac, pick if pick is not None else [])
    changed = True
    while changed:
        changed = False
        for tag in ("sdt", "moveTo", "hyperlink", "dir", "bdo", "smartTag",
                    "customXml", "fldSimple"):
            for el in list(root.iter("{%s}%s" % (W, tag))):
                if tag == "hyperlink":
                    # A printed book cannot click: link text prints like the
                    # words around it, with no web underline and no blue
                    # (Gemini executive ruling 2026-10-23).
                    for _rpr in el.iter("{%s}rPr" % W):
                        for _kid in list(_rpr):
                            _ln = _kid.tag.split("}")[-1]
                            if _ln in ("u", "color") or (
                                    _ln == "rStyle" and "hyperlink" in str(_kid.get("{%s}val" % W) or "").lower()):
                                _rpr.remove(_kid)
                if tag == "sdt":
                    content = el.find("{%s}sdtContent" % W)
                    _unwrap(el, content if content is not None else [])
                else:
                    keep = [c for c in el if c.tag not in (
                        "{%s}smartTagPr" % W, "{%s}customXmlPr" % W)]
                    _unwrap(el, keep)
                changed = True
    return root


def _extract_run_into(child, runs, images, with_notes=True):
    """Pull text (with breaks/tabs), bold/italic, and any image embeds from a
    single <w:r> run into runs/images. Field instruction codes are never emitted.

    A run holding a footnote or endnote reference leaves a raised number
    behind, so the reader can find the note at the back of the book. Pass
    with_notes=False to read the same run without those numbers."""
    rpr = child.find(qn("w:rPr"))
    bold = False
    italic = False
    underline = strike = small_caps = superscript = subscript = False
    if rpr is not None:
        bold = _xml_toggle_on(rpr, "w:b")
        italic = _xml_toggle_on(rpr, "w:i")
        strike = _xml_toggle_on(rpr, "w:strike")
        small_caps = _xml_toggle_on(rpr, "w:smallCaps")
        _u = rpr.find(qn("w:u"))
        if _u is not None:
            underline = str(_u.get(qn("w:val")) or "single").strip().lower() != "none"
        _va = rpr.find(qn("w:vertAlign"))
        if _va is not None:
            _v = str(_va.get(qn("w:val")) or "").strip().lower()
            superscript = _v == "superscript"
            subscript = _v == "subscript"
    text_parts = []
    note_markers = []
    for node in child:
        ntag = node.tag.split("}")[-1] if "}" in node.tag else node.tag
        if with_notes and ntag in ("footnoteReference", "endnoteReference"):
            _n = _note_number_for(
                node, "footnote" if ntag == "footnoteReference" else "endnote")
            if _n:
                note_markers.append(_n)
        elif ntag == "t":
            if node.text:
                text_parts.append(node.text)
        elif ntag == "cr":
            text_parts.append("\n")
        elif ntag == "br" and node.get(qn("w:type")) in (None, "textWrapping"):
            text_parts.append("\n")
        elif ntag == "tab":
            text_parts.append("\t")
        elif ntag == "ptab":
            text_parts.append("\t")
        elif ntag == "noBreakHyphen":
            # "well-known" typed with Ctrl+Shift+Hyphen. Dropped until
            # 2026-09-25, printing "wellknown" (blind audit B4).
            text_parts.append("-")
        elif ntag == "sym" and _sym_is_picture_font(node):
            # A Wingdings smiley or arrow: kept as the same character in the
            # same picture font, so it prints exactly as the author saw it.
            _t = "".join(text_parts)
            if _t:
                runs.append(RichRun(_t, bold, italic, underline, strike,
                                    small_caps, superscript, subscript))
            text_parts = []
            try:
                _pc = int(node.get(qn("w:char")) or "0", 16)
            except ValueError:
                _pc = 0
            if _pc:
                if _pc < 0xF000:
                    _pc += 0xF000
                runs.append(RichRun(chr(_pc), bold, italic, underline, strike,
                                    small_caps, superscript, subscript,
                                    font=node.get(qn("w:font"))))
        elif ntag == "sym":
            # A character typed with Word's Insert, then Symbol. Until
            # 2026-09-21 it was dropped in silence, taking em dashes, currency
            # signs, accented letters and scene-break ornaments with it. The
            # code is stored as hexadecimal, usually in the private-use area
            # F000 to F0FF, which is the same character 61440 lower down.
            _code = node.get(qn("w:char")) or ""
            try:
                _n = int(_code, 16)
            except ValueError:
                _n = 0
            if 0xF000 <= _n <= 0xF0FF:
                _n -= 0xF000
            # The Symbol font draws Greek and maths in the places of plain
            # letters: its "a" is an alpha. Printed in the book font it came
            # out as "a" until 2026-09-25 (blind audit B4).
            if (node.get(qn("w:font")) or "").strip().lower() == "symbol":
                _n = _SYMBOL_FONT_TO_UNICODE.get(_n, _n)
            if 32 <= _n <= 0x10FFFF:
                text_parts.append(chr(_n))
    drawing = child.find(qn("w:drawing"))
    if drawing is not None:
        for _img_tag in ("wp:inline", "wp:anchor"):
            _img = drawing.find(qn(_img_tag))
            if _img is not None:
                blip = _img.find(".//" + qn("a:blip"))
                if blip is not None:
                    r_embed = blip.get(qn("r:embed"))
                    if r_embed:
                        _ext = _img.find(qn("wp:extent"))
                        _cx = int(_ext.get("cx", "0")) if _ext is not None else 0
                        _cy = int(_ext.get("cy", "0")) if _ext is not None else 0
                        images.append((r_embed, _cx, _cy))
    text = "".join(text_parts)
    if text:
        runs.append(RichRun(text, bold, italic, underline, strike,
                            small_caps, superscript, subscript))
    for _n in note_markers:
        runs.append(RichRun(str(_n), superscript=True))


def extract_paragraph_content(para, with_notes=True):
    """Extract rich content from a source paragraph, preserving runs and images.

    with_notes=False reads the same paragraph without the raised footnote /
    endnote numbers, which the paragraph-accounting check needs so it can
    recognise a line either way."""
    runs = []
    images = []

    for child in para._element:
        tag = child.tag.split("}")[-1] if "}" in child.tag else child.tag
        if tag == "r":
            _extract_run_into(child, runs, images, with_notes)
        elif tag == "fldSimple":
            # Simple field: keep the displayed result runs, not the field code
            for _r in child.iter(qn("w:r")):
                _extract_run_into(_r, runs, images, with_notes)
        elif tag == "hyperlink":
            # Extract text from hyperlink runs
            for r in child.findall(qn("w:r")):
                for t in r.findall(qn("w:t")):
                    if t.text:
                        runs.append(RichRun(t.text, False, False))
        elif tag in ("sdt", "smartTag", "customXml", "ins", "bookmarkStart"):
            # A content control (w:sdt), a smart tag, or a custom-XML wrapper
            # holds ordinary runs inside it. Until 2026-09-21 nothing looked
            # inside them, so every word a Word template or an older version of
            # Word had wrapped was dropped from the finished book without a
            # word of warning, and the accounting check could not see it
            # because it used this same reader. Gemini ruled silent loss of the
            # author's words a blocker (AGREED SPEC, the bar for shipping).
            for _r in child.iter(qn("w:r")):
                _extract_run_into(_r, runs, images, with_notes)

    return runs, images


def _list_kind_from_numbering(para, doc):
    """Resolve a paragraph's direct numbering (w:numPr) to 'bullet' or 'number'
    by reading the numbering definition. None if it has no direct numbering."""
    ppr = para._p.find(qn("w:pPr"))
    if ppr is None:
        return None
    numpr = ppr.find(qn("w:numPr"))
    if numpr is None:
        return None
    nid_el = numpr.find(qn("w:numId"))
    if nid_el is None:
        return "bullet"
    nid = nid_el.get(qn("w:val"))
    try:
        numbering = doc.part.numbering_part.element
    except Exception:
        return "bullet"
    num = next((n for n in numbering.findall(qn("w:num"))
                if n.get(qn("w:numId")) == nid), None)
    if num is None:
        return "bullet"
    abs_el = num.find(qn("w:abstractNumId"))
    if abs_el is None:
        return "bullet"
    absid = abs_el.get(qn("w:val"))
    absnum = next((a for a in numbering.findall(qn("w:abstractNum"))
                   if a.get(qn("w:abstractNumId")) == absid), None)
    if absnum is None:
        return "bullet"
    lvl = absnum.find(qn("w:lvl"))
    fmt = lvl.find(qn("w:numFmt")) if lvl is not None else None
    val = fmt.get(qn("w:val")) if fmt is not None else None
    return "bullet" if val in (None, "bullet", "none") else "number"


def table_position(para):
    """Where a paragraph sits inside a plain top-level table: (key, row,
    column, rows, columns), or None. A table nested inside another table is
    left as loose lines, the way it always was, because it cannot be laid out
    safely on a 6-inch page."""
    tc = para._element.getparent()
    if tc is None or tc.tag != qn("w:tc"):
        return None
    tr = tc.getparent()
    tbl = tr.getparent() if tr is not None else None
    if tbl is None or tbl.tag != qn("w:tbl"):
        return None
    body = tbl.getparent()
    if body is None or body.tag != qn("w:body"):
        return None
    rows = [r for r in tbl.iterchildren() if r.tag == qn("w:tr")]
    cells = [c for c in tr.iterchildren() if c.tag == qn("w:tc")]
    ncols = max(len([c for c in r.iterchildren() if c.tag == qn("w:tc")]) for r in rows)
    return (id(tbl), rows.index(tr), cells.index(tc), len(rows), ncols)


def detect_list_level(para):
    """How deep a Word list item sits: 0 for a main point, 1 for a sub-point.
    Read from the paragraph's own list level, or from a style named like
    "List Bullet 2". Capped at 3 so a deep list cannot run off the page."""
    level = 0
    try:
        ppr = para._p.find(qn("w:pPr"))
        numpr = ppr.find(qn("w:numPr")) if ppr is not None else None
        ilvl = numpr.find(qn("w:ilvl")) if numpr is not None else None
        if ilvl is not None and str(ilvl.get(qn("w:val"), "0")).isdigit():
            level = int(ilvl.get(qn("w:val")))
        else:
            name = (para.style.name or "").strip().lower()
            m = re.match(r"list (bullet|number|paragraph|continue)\s+(\d)$", name)
            if m:
                level = int(m.group(2)) - 1
    except Exception:
        level = 0
    return max(0, min(level, 3))


def detect_list_kind(para, doc):
    """Return 'bullet'/'number' if the source paragraph is a Word list item, else
    None. Checks the list STYLE name first (List Bullet / List Number), then any
    direct numbering. Plain paragraphs return None so they are never bulletized."""
    try:
        name = (para.style.name or "").lower()
    except Exception:
        name = ""
    if "list number" in name:
        return "number"
    if "list bullet" in name:
        return "bullet"
    return _list_kind_from_numbering(para, doc)


INVISIBLE_CHARACTERS = {
    "\u00ad": "",    # soft hyphen - prints as a real hyphen on paper
    "\u200b": "",    # zero width space - splits a word for anyone searching
    # The zero width joiner and non-joiner are kept: they are part of how
    # Persian, Urdu, Hindi and emoji words are spelled. Taking them out merged
    # Persian words and stopped the book (second blind audit D4, 2026-09-25).
    "\ufeff": "",    # byte order mark, left behind by some editors
    "\u2060": "",    # word joiner
}


_EMOJI_JOINED = re.compile(
    "([\U0001F000-\U0001FAFF\u2600-\u27BF\uFE0F\U0001F3FB-\U0001F3FF])"
    "\u200d"
    "(?=[\U0001F000-\U0001FAFF\u2600-\u27BF])")


_JOINER_KEEP = "\uE000JOIN\uE000"


def strip_invisible_characters(text):
    """Take out the characters that print or break words but cannot be seen."""
    if not text:
        return text
    if "\u200d" in text:
        text = _EMOJI_JOINED.sub(lambda m: m.group(1) + _JOINER_KEEP, text)
    for bad, good in INVISIBLE_CHARACTERS.items():
        if bad in text:
            text = text.replace(bad, good)
    return text.replace(_JOINER_KEEP, "\u200d")


def clean_text(text):
    """Clean formatting artifacts from raw text."""
    cleaned = strip_invisible_characters(text).strip().lstrip("\t")
    cleaned = re.sub(r"\.{3,}\d*\s*$", "", cleaned).strip()
    return cleaned


def _apply_buyer_corrections(blocks, config):
    """THE BUYER MAY SAY "THAT LINE IS NOT A CHAPTER".

    Gemini overturned its own earlier ruling on 2026-09-19 and put this in the
    first release: if the program reads something as a chapter and the buyer
    can see it is not, the program takes the correction, rather than sending
    them into Word to operate on their own manuscript.
    The window lists the chapters found and the buyer unticks any wrong one.
    Those positions arrive here as "not_chapters", counting the chapters from 1
    in the order they were found. An unticked chapter keeps every word it had:
    its title becomes an ordinary line and its paragraphs join the chapter
    before it, so nothing is ever lost by unticking.
    """
    wrong = set((config or {}).get("not_chapters") or [])
    if not wrong:
        return blocks
    kept, seen = [], 0
    for block in blocks:
        if block.get("type") == "chapter" and str(block.get("title", "")).strip():
            seen += 1
            if seen in wrong:
                title = str(block.get("title", "")).strip()
                moved = ([ContentParagraph(runs=[RichRun(title)])] if title else []) \
                        + list(block.get("paragraphs", []))
                host = None
                for earlier in reversed(kept):
                    if earlier.get("type") == "chapter":
                        host = earlier
                        break
                if host is not None:
                    host["paragraphs"].extend(moved)
                else:
                    kept.append({"type": "chapter", "title": "", "paragraphs": moved})
                print('  You said "%s" is not a chapter, so its words were kept '
                      'as ordinary text.' % title[:48])
                continue
        kept.append(block)
    return kept


def parse_manuscript(doc, config=None):
    """Parse a raw manuscript into structured content blocks.

    Heading detection is config-driven via the 'heading_style' key (default
    'auto'): 'auto' first tries the literal 'Chapter N' style and, if that finds
    NO chapters, retries with broad detection (Word heading styles, numbered
    'N. Title' lines, standalone bold / ALL-CAPS lines) so NUMBERED or NAMED
    nonfiction sections are recognized instead of collapsing into one block.
    Set 'heading_style' to 'chapter' to force the original literal-only behavior,
    or to 'styles' / 'numbered' / 'bold' / 'allcaps' to force a single signal.

    When Word heading styles are present, only paragraphs at the minimum (top)
    heading level become chapter breaks. Lower heading levels become bold subheads
    within the chapter. Fuzzy signals (numbered, bold, ALL-CAPS) are suppressed
    entirely when any Word heading styles exist."""
    # Read the author's footnotes and endnotes first, so every reading of a
    # paragraph from here on leaves the raised number where the note was.
    load_notes(doc)

    mode = "auto"
    if config:
        mode = str(config.get("heading_style", "auto") or "auto").strip().lower()
        if mode not in HEADING_MODES:
            mode = "auto"

    # Find the highest-priority heading level present in the document.
    min_level = _min_heading_level(doc)
    # The book's TITLE in Heading 1 and every chapter in Heading 2 is a common
    # way to set up a manuscript. Sherlock Holmes, Walden and Dubliners laid
    # out that way came out as two chapters, or were refused as one
    # (16-novel test, 2026-09-25; Gemini approved the fix). With exactly one
    # top-level heading and two or more at the next level, the next level holds
    # the chapters, and the lone top heading is read as the title.
    # Only when that lone heading sits above the prose, like a title: a real
    # chapter heading followed by its text and then Heading 2 subheads is a
    # one-chapter book, which is refused as one (unchanged).
    if min_level is not None:
        _levels = Counter(para_heading_level(p) for p in iter_doc_paragraphs(doc))
        if _levels.get(min_level, 0) == 1 and _levels.get(min_level + 1, 0) >= 2:
            _prose_before = 0
            _seen_top = False
            for _p in iter_doc_paragraphs(doc):
                _lv = para_heading_level(_p)
                if _lv == min_level:
                    _seen_top = True
                    continue
                if _seen_top and _lv == min_level + 1:
                    break
                if _seen_top and _lv is None:
                    _prose_before += len((_p.text or "").split())
            if _seen_top and _prose_before <= 40:
                min_level = min_level + 1

    if mode == "auto":
        if min_level is not None:
            # Styles are present: use only the top-level heading as chapter break.
            blocks = _parse_manuscript(doc, make_heading_detector("auto", min_level, doc), min_level)
            # But a lone styled heading (usually the author's title styled
            # Heading 1) with the real chapters typed as ALL-CAPS, bold or
            # numbered lines is a beginner's manuscript, not a one-chapter
            # book. Fewer than two styled chapters: retry with the broad
            # signals, styles ignored. (Edge battery on the .exe, 2026-09-10.)
            if sum(1 for b in blocks if b["type"] == "chapter") < 2:
                # Only when the styled headings are ALL top-level (one lone
                # title). A book with one Heading 1 and Heading 2 subheads is
                # a real one-chapter book and keeps its structure.
                lower_styled = sum(
                    1 for para in iter_doc_paragraphs(doc)
                    if (para_heading_level(para) or 0) > min_level)
                if lower_styled == 0:
                    broad = _parse_manuscript(doc, make_heading_detector("auto", None, doc))
                    if sum(1 for b in broad if b["type"] == "chapter") >= 2:
                        return _apply_buyer_corrections(broad, config)
            return _apply_buyer_corrections(blocks, config)
        # No heading styles: try literal chapters first, then broad detection.
        blocks = _parse_manuscript(doc, make_heading_detector("chapter", None, doc))
        # A novel that opens with "Prologue", or has a "Part One" divider, used
        # to be refused outright with "Only one chapter was found". The broad
        # search that finds bold, centred chapter titles only ran when the
        # strict search found NO chapters at all, and one Prologue line made it
        # one, so the real titles were never looked for. An independent audit
        # found this on 2026-09-21. The styles branch above always had the
        # right guard. One chapter is not a book, so one is not enough to stop
        # looking.
        if sum(1 for b in blocks if b["type"] == "chapter") < 2:
            # No literal chapters — retry with the broad detector so numbered /
            # named / styled sections aren't lost.
            blocks = _parse_manuscript(doc, make_heading_detector("auto", None, doc))
        return _apply_buyer_corrections(blocks, config)
    return _apply_buyer_corrections(
        _parse_manuscript(doc, make_heading_detector(mode, min_level, doc), min_level), config)


_NAME_WORD = r"(?:[A-Z][\w'\u2019\-]*\.?|\([A-Z][\w'\u2019\-]*\)|de|van|von|du|da|la|le|der)"


_BYLINE_HEADING = re.compile(r"^[Bb][Yy]\s+[A-Z][\w'\u2019\-]*\.?(?:\s+" + _NAME_WORD + r"){1,5}$")


def _author_block_style(para, text):
    """S8 (Gemini ruling 2026-10-24). Keep the author's own setup for letters,
    diary entries and quoted passages instead of guessing which they are:
    a paragraph styled Quote (or Intense Quote, Block Text) or indented on the
    left by a quarter inch or more prints as an indented block, and a short
    right-aligned line (a sign-off) stays right-aligned."""
    try:
        name = (_style_name_of(para) or "").lower()
    except Exception:
        name = ""
    if "quote" in name or name in ("block text",):
        return "indent"
    try:
        _first, left, _right = _indents_in(para)
    except Exception:
        left = 0.0
    if left >= 0.25:
        return "indent"
    align = para.alignment
    st = para.style
    while align is None and st is not None:
        align = getattr(getattr(st, "paragraph_format", None), "alignment", None)
        st = st.base_style
    if align == WD_ALIGN_PARAGRAPH.RIGHT and len((text or "").split()) <= 12:
        return "right"
    return None


def _parse_manuscript(doc, is_heading, min_level=None):
    """Parse a raw manuscript into structured content blocks using the given
    heading detector. (See parse_manuscript for the public entry point.)

    Each block has:
      type: 'chapter' | 'dedication' | 'acknowledgments' | back-matter type | etc.
      title: heading text
      paragraphs: list of ContentParagraph objects (preserving rich text)

    When min_level is set, paragraphs whose heading level is greater than
    min_level become subheads (ContentParagraph with is_subhead=True) rather
    than new chapter blocks.
    """
    blocks = []
    current_block = None
    # IS THIS A BOOK WHOSE CHAPTER TITLES SIT AT THE FRONT OF THEIR OWN FIRST
    # PARAGRAPH? Two or more such paragraphs say yes; one bold opening phrase
    # does not. Only then is a paragraph split (R8, 2026-09-22).
    _runin_book = False
    if min_level is None:
        _runin_seen = 0
        for _p in iter_doc_paragraphs(doc):
            if not _p.text.strip():
                continue
            _t, _n = _runin_heading_split(_p.runs)
            if _t and not is_front_matter_heading(_t) and not is_back_matter_heading(_t):
                _runin_seen += 1
                if _runin_seen >= 2:
                    _runin_book = True
                    break
    in_back_matter = False
    in_toc = False  # Inside a Table of Contents block — skip chapter-like entries
    toc_pending = None  # (heading text, ContentParagraph); may be the real chapter 1
    toc_block = None
    nonempty_idx = -1  # counts classified content lines, for the title-block skip
    # True while the paragraph just read carried a picture, so the next one can
    # be recognised as its caption.
    _last_para_had_picture = [False]
    # False until the first ordinary (non Title/Subtitle) paragraph is seen.
    # Guards the title-page rule so a later Title-styled line is never dropped.
    _seen_body_para = [False]
    _title_lines_seen = [0]
    # How often each short line occurs in the whole manuscript. A typed contents
    # list with NO page numbers repeats the book's own headings, so a short line
    # inside it that occurs again elsewhere is a contents line (2026-09-24,
    # Mike's Agnostic manuscript: "Acknowledgments" and "Dedication" in such a
    # list ended the list early and the run stopped with no file).
    _line_counts = Counter(
        re.sub(r"\s+", " ", (p.text or "").strip().lower())
        for p in iter_doc_paragraphs(doc) if (p.text or "").strip())

    def _typed_contents_line(t):
        k = re.sub(r"\s+", " ", t.strip().lower())
        if not k or len(k.split()) > 12 or k.endswith((".", "?", "!", '"')):
            return False
        return _line_counts.get(k, 0) >= 2 or is_front_matter_heading(t)

    for para in iter_doc_paragraphs(doc):
        raw_text = para.text.strip()
        in_table_cell = _paragraph_is_in_table(para)

        # Check for image-only paragraphs (no text but has inline images)
        if not raw_text:
            has_image = (
                len(list(para._element.iter(qn("wp:inline")))) > 0 or
                len(list(para._element.iter(qn("wp:anchor")))) > 0
            )
            has_field = len(list(para._element.iter(qn("w:fldSimple")))) > 0
            if has_image or has_field:
                # Image-only paragraph — extract and keep it. Start an
                # unclassified block if none is open yet, so picture books with
                # no text headings aren't silently dropped.
                runs, images = extract_paragraph_content(para)
                if runs or images:
                    if current_block is None:
                        current_block = {"type": "unclassified", "title": "",
                                         "paragraphs": []}
                        blocks.append(current_block)
                    current_block["paragraphs"].append(
                        ContentParagraph(runs=runs, images=images))
            continue

        # Keep the source-visible text unchanged. Classification may normalize
        # whitespace, but output content must use the original visible wording.
        text = raw_text
        if not text:
            continue

        # Extract rich content
        runs, images = extract_paragraph_content(para)
        # MARKDOWN HEADING MARKS (2026-09-24, found on Mike's own draft "The
        # Cartographer's Compass"). A book drafted in an AI chat and pasted into
        # Word keeps "## Chapter 1: ..." with the hash marks typed in, so no
        # chapter was found and the book was refused. The marks are taken off a
        # line that has words after them. A lone "#" is a scene break (R6) and
        # is not touched.
        _md = re.match(r"^#{1,6}[ \t]+(\S.*)$", text)
        # "# # #" and "#  *  #" are scene breaks, not headings: only a line with
        # a real word after the marks is a markdown heading.
        if _md and not re.search(r"[^\W_]", _md.group(1)):
            _md = None
        if _md:
            text = _md.group(1).strip()
            _left = True
            for _r in runs:
                if not _left:
                    break
                _t = _r.text or ""
                _new = _t.lstrip(" \t#")
                if _new:
                    _left = False
                _r.text = _new
            runs = [_r for _r in runs if (_r.text or "")] or runs
        try:
            _style_name = (para.style.name or "").strip().lower()
        except Exception:
            _style_name = ""
        # Only the manuscript's OPENING run of Title/Subtitle paragraphs is the
        # author's own title page. Once any ordinary paragraph appears, a later
        # Title-styled line is real content (a dedication, a part opener) and
        # must never be dropped.
        # ONLY the document's very first Title/Subtitle line is treated as the
        # author's own title page. A second one is real content -- a dedication,
        # a subtitle the author wants printed, a part opener -- and losing it is
        # worse than printing it in the wrong place, so it is always kept.
        _is_titlepage = False
        if _style_name in ("title", "subtitle"):
            if not _seen_body_para[0] and _title_lines_seen[0] == 0:
                _is_titlepage = True
            _title_lines_seen[0] += 1
        else:
            _seen_body_para[0] = True
        # A PICTURE CAPTION. Until 2026-09-19 a caption was treated as ordinary
        # body text: an author's centred 9 point "Figure 1. The mill at Big Bay"
        # came back justified at 11 point, which reads as a stray sentence under
        # the picture rather than a caption. A caption is a SHORT line that
        # either sits directly under a picture, or names itself with Figure,
        # Fig., Photo, Image, Plate or Table and a number.
        _looks_like_caption = False
        _plain = clean_text(text)
        if _plain and not images and len(_plain.split()) <= 25:
            _after_picture = bool(_last_para_had_picture[0])
            _names_itself = bool(CAPTION_PATTERN.match(_plain))
            _was_centred = (para.alignment == WD_ALIGN_PARAGRAPH.CENTER)
            _looks_like_caption = _names_itself or (_after_picture and _was_centred)
        _last_para_had_picture[0] = bool(images)

        cp = ContentParagraph(runs=runs, images=images,
                              list_kind=detect_list_kind(para, doc),
                              list_level=detect_list_level(para),
                              is_title_style=_is_titlepage,
                              is_caption=_looks_like_caption)
        if in_table_cell:
            cp.table_pos = table_position(para)
        elif cp.list_kind is None:
            cp.block_style = _author_block_style(para, text)

        # Scene break detection
        if is_scene_break(text):
            if current_block is not None:
                current_block["paragraphs"].append(
                    ContentParagraph(is_scene_break=True))
            continue

        # If we're inside a TOC block, skip chapter/section heading lines
        # (they're TOC entries, not actual chapters). Break out on anything
        # that isn't a heading pattern — that means real content has started.
        if in_toc:
            # A TYPED CONTENTS LAID OUT AS A TABLE (Alice in Wonderland, outside
            # test 2026-10-23, Gemini ruling A). Every cell belongs to the
            # contents and goes with it; a table cell is never a chapter. Before
            # this, the first cell "CHAPTER I." became a fake chapter and the
            # rest of the table was printed in the book.
            if in_table_cell:
                if toc_block is not None:
                    if toc_pending is not None:
                        toc_block["paragraphs"].append(toc_pending[1])
                        toc_pending = None
                    toc_block["paragraphs"].append(cp)
                continue
            if is_toc_entry(para.text):
                # A dot-leader/tabbed entry is definitely part of the manually
                # typed TOC. Keep it until the builder either preserves the old
                # TOC or replaces it with the generated TOC and prints a notice.
                if toc_pending is not None and toc_block is not None:
                    toc_block["paragraphs"].append(toc_pending[1])
                    toc_pending = None
                if toc_block is not None:
                    toc_block["paragraphs"].append(cp)
                continue
            is_heading_text = (is_chapter_heading(text) or
                               bool(SECTION_HEADING_PATTERN.match(text.strip())) or
                               _typed_contents_line(text))
            if is_heading_text:
                # Looks like a TOC entry — but it may be the FIRST REAL chapter
                # heading (a real ToC is followed by more entries or ends; the real
                # chapter is followed by body prose). Remember it; if body text comes
                # next, we resurrect it below instead of dropping it AND its body.
                if toc_pending is not None and toc_block is not None:
                    # Consecutive heading-like lines inside a manually typed TOC:
                    # all but the last are confirmed TOC entries.
                    toc_block["paragraphs"].append(toc_pending[1])
                toc_pending = (text, cp)
                continue
            else:
                # Body text — the TOC is over. If a heading was pending it was the
                # first real chapter (the ToC's own dot-leader entries were already
                # filtered out above), so open it now so its body isn't lost.
                in_toc = False
                if toc_pending is not None:
                    in_back_matter = False
                    current_block = {"type": "chapter",
                                     "title": toc_pending[0], "paragraphs": []}
                    blocks.append(current_block)
                    toc_pending = None
                elif current_block is toc_block:
                    # PROSE RIGHT AFTER A TYPED CONTENTS (Walden's epigraph,
                    # outside test 2026-10-23). It is not part of the contents:
                    # until this day it joined the contents block and was
                    # deleted along with it. It now opens the untitled pages
                    # before Chapter One, so every word is printed.
                    current_block = None
                # Fall through to normal handling below

        # This line will be classified — count it for the title-block skip.
        nonempty_idx += 1

        # Section heading detection (order matters)
        _lower_heading = text.strip().lower().replace("’", "'")
        _post_body_ack = (
            _lower_heading in ("acknowledgments", "acknowledgements", "acknowledgment")
            and any(b.get("type") == "chapter" for b in blocks)
        )
        if not in_table_cell and (is_back_matter_heading(text) or _post_body_ack):
            in_back_matter = True
            bm_type = _lower_heading
            if bm_type in ("acknowledgements", "acknowledgment"):
                bm_type = "acknowledgments"
            bm_type_key = bm_type.replace("’", "'")
            # Do not merge repeated back-matter headings. Every visible heading
            # remains represented in the output in source order.
            current_block = {
                "type": bm_type_key,
                "title": text.strip(),
                "paragraphs": [],
                "is_back_matter": True,
            }
            blocks.append(current_block)
        elif (not in_table_cell and _BYLINE_HEADING.match(text.strip())
              and not any(b.get("type") == "chapter" for b in blocks)
              and is_heading(text, runs, para, nonempty_idx)):
            # A BYLINE STYLED AS A HEADING before the first chapter ("by Arthur
            # Conan Doyle" in Heading 1, outside test 2026-10-23, Gemini ruling
            # B) is the old title page, never a chapter. It joins the opening
            # lines, where the title-page rules replace it when it matches the
            # author typed in the window and keep it as plain text when not.
            if not blocks or blocks[-1]["type"] != "unclassified":
                blocks.append({"type": "unclassified", "title": "", "paragraphs": []})
            current_block = blocks[-1]
            current_block["paragraphs"].append(cp)
        elif not in_table_cell and is_heading(text, runs, para, nonempty_idx):
            # Chapter/section headings always start a new chapter block
            in_back_matter = False
            current_block = {"type": "chapter", "title": text, "paragraphs": []}
            blocks.append(current_block)
        elif not in_table_cell and _runin_book and _runin_heading_split(runs)[0] and \
                (nonempty_idx > 1 or re.match(r"^chapter\b", str(_runin_heading_split(runs)[0]).strip(), re.I)) and \
                not is_front_matter_heading(text) \
                and not is_back_matter_heading(text):
            # The chapter title is typed into the front of its own first
            # paragraph. Open the chapter on the title and keep the rest of the
            # paragraph as that chapter's first line, so nothing is lost and
            # the buyer is not told there were no chapter headings (R8).
            _title, _lead = _runin_heading_split(runs)
            in_back_matter = False
            current_block = {"type": "chapter", "title": _title, "paragraphs": []}
            blocks.append(current_block)
            _real = [r for r in runs if r.text.strip()]
            _tail = _real[_lead:]
            if _tail:
                _first = _tail[0]
                _first.text = _first.text.lstrip()
                current_block["paragraphs"].append(
                    ContentParagraph(runs=_tail, images=images))
        elif (not in_table_cell and min_level is not None and not in_back_matter
              and para_heading_level(para) is not None
              and para_heading_level(para) != min_level):
            # Lower heading level (H2, H3, …) — demote to a bold subhead within
            # the current chapter; no new page break or section break.
            if (current_block is None and not blocks
                    and para_heading_level(para) < min_level):
                # The book's own title in Heading 1 above chapters in Heading 2
                # (2026-09-25). It is the title page, not a chapter: kept with
                # the opening lines, and regenerated on the new title page.
                cp = ContentParagraph(runs=runs, images=images, is_title_style=True)
                current_block = {"type": "unclassified", "title": "", "paragraphs": [cp]}
                blocks.append(current_block)
            elif current_block is not None:
                cp = ContentParagraph(runs=runs, images=images, is_subhead=True)
                current_block["paragraphs"].append(cp)
            else:
                # No chapter open yet — open one so content isn't orphaned.
                current_block = {"type": "chapter", "title": text, "paragraphs": []}
                blocks.append(current_block)
        elif not in_table_cell and is_front_matter_heading(text) and (
                not in_back_matter
                or not any(_b.get("type") == "chapter" and (_b.get("title") or "").strip()
                           for _b in blocks)):
            # Before the first chapter, an Acknowledgments page does not make
            # what follows back matter: an Introduction after it is still the
            # Introduction (Mike's agnostic book, 2026-10-19).
            in_back_matter = False
            fm_type = text.strip().lower()
            if fm_type in ("acknowledgments", "acknowledgements", "acknowledgment"):
                fm_type = "acknowledgments"
            if fm_type.startswith("welcome to "):
                fm_type = "introduction"
            _ft = _FRONT_TITLED.match(fm_type)
            if _ft:
                fm_type = _ft.group(1)
            # Entering a TOC block — set flag to skip chapter-like entries
            if fm_type in ("table of contents", "contents"):
                in_toc = True
                current_block = {"type": fm_type, "title": text, "paragraphs": []}
                blocks.append(current_block)
                toc_block = current_block
            else:
                # Check for duplicate: merge into existing
                existing = None
                for b in blocks:
                    if b["type"] == fm_type:
                        existing = b
                        break
                if existing is not None:
                    current_block = existing
                else:
                    current_block = {"type": fm_type, "title": text, "paragraphs": []}
                    blocks.append(current_block)
        elif current_block is not None:
            current_block["paragraphs"].append(cp)
        else:
            # Pre-heading content
            if not blocks or blocks[-1]["type"] != "unclassified":
                current_block = {"type": "unclassified", "title": "", "paragraphs": []}
                blocks.append(current_block)
            current_block = blocks[-1]
            current_block["paragraphs"].append(cp)

    # A TOC that ends the document may leave one final heading-like entry pending.
    if toc_pending is not None and toc_block is not None:
        toc_block["paragraphs"].append(toc_pending[1])

    return blocks


def accept_tracked_changes(doc):
    """Accept tracked revisions before parsing so inserted text is not lost:
    keep <w:ins> content (unwrap) and drop <w:del> content. Prints a notice."""
    from docx.oxml.ns import qn
    root = doc.element
    n_del = n_ins = 0
    for dele in list(root.iter(qn('w:del'))):
        p = dele.getparent()
        if p is not None:
            p.remove(dele); n_del += 1
    for ins in list(root.iter(qn('w:ins'))):
        p = ins.getparent()
        if p is None:
            continue
        idx = list(p).index(ins)
        for child in list(ins):
            p.insert(idx, child); idx += 1
        p.remove(ins); n_ins += 1
    if n_ins or n_del:
        print("  Note: accepted tracked changes (%d insertion(s) kept, %d deletion(s) removed) so no edited text is lost." % (n_ins, n_del))
    return doc

